export const categories = [
  { slug: 'featured', label: 'Featured products' },
  { slug: 'sale', label: 'Products on sale' },
] as const

export type CategorySlug = (typeof categories)[number]['slug']

export function getCategoryHeading(category: string) {
  return categories.find((entry) => entry.slug === category)?.label ?? 'Featured products'
}

export const categories = [
  { slug: 'featured', label: 'Featured products' },
  { slug: 'sale', label: 'Products on sale' },
] as const

export type CategorySlug = (typeof categories)[number]['slug']

export function getCategoryHeading(category: string) {
  return categories.find((entry) => entry.slug === category)?.label ?? 'Featured products'
}

export type CategorySnapshot = {
  heading: string
  products: string[]
}

const snapshots = new Map<string, CategorySnapshot>()
const inflight = new Map<string, Promise<CategorySnapshot>>()

export function getCategorySnapshot(category: string) {
  return snapshots.get(category)
}

export function setCategorySnapshot(category: string, snapshot: CategorySnapshot) {
  snapshots.set(category, snapshot)
}

export function getInflightPrefetch(category: string) {
  return inflight.get(category)
}

export function setInflightPrefetch(category: string, promise: Promise<CategorySnapshot>) {
  inflight.set(category, promise)
}

export function clearInflightPrefetch(category: string) {
  inflight.delete(category)
}

export type CategorySnapshot = {
  heading: string
  products: string[]
}

const snapshots = new Map<string, CategorySnapshot>()
const inflight = new Map<string, Promise<CategorySnapshot>>()

export function getCategorySnapshot(category: string) {
  return snapshots.get(category)
}

export function setCategorySnapshot(category: string, snapshot: CategorySnapshot) {
  snapshots.set(category, snapshot)
}

export function getInflightPrefetch(category: string) {
  return inflight.get(category)
}

export function setInflightPrefetch(category: string, promise: Promise<CategorySnapshot>) {
  inflight.set(category, promise)
}

export function clearInflightPrefetch(category: string) {
  inflight.delete(category)
}

import {
  clearInflightPrefetch,
  getCategorySnapshot,
  getInflightPrefetch,
  setCategorySnapshot,
  setInflightPrefetch,
  type CategorySnapshot,
} from '@/lib/category-cache'
import { getCategoryHeading } from '@/lib/categories'

async function fetchCategorySnapshot(category: string): Promise<CategorySnapshot> {
  const response = await fetch(`/api/catalog?category=${encodeURIComponent(category)}`)

  if (!response.ok) {
    throw new Error(`Failed to prefetch category: ${category}`)
  }

  const data = (await response.json()) as CategorySnapshot
  setCategorySnapshot(category, data)
  return data
}

export function prefetchCategory(category: string) {
  const cached = getCategorySnapshot(category)
  if (cached) {
    return Promise.resolve(cached)
  }

  const inflight = getInflightPrefetch(category)
  if (inflight) {
    return inflight
  }

  const promise = fetchCategorySnapshot(category)
    .catch((error) => {
      const fallback: CategorySnapshot = {
        heading: getCategoryHeading(category),
        products: [],
      }
      setCategorySnapshot(category, fallback)
      return fallback
    })
    .finally(() => {
      clearInflightPrefetch(category)
    })

  setInflightPrefetch(category, promise)
  return promise
}

